import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Business Analysis & Functional Baseline (docs/ba/)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/README.md","filePath":"ba/README.md"}'),n={name:"ba/README.md"};function c(s,e,l,i,r,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="business-analysis-functional-baseline-docs-ba" tabindex="-1">Business Analysis &amp; Functional Baseline (<code>docs/ba/</code>) <a class="header-anchor" href="#business-analysis-functional-baseline-docs-ba" aria-label="Permalink to &quot;Business Analysis &amp; Functional Baseline (`docs/ba/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../database/README.html">← Database Architecture</a> · <a href="./use-cases/README.html">Use Cases (<code>UC-001</code>–<code>UC-141</code>)</a> · <a href="./../feature/README.html">Feature Specifications (<code>srs/</code> &amp; <code>modules/</code>) →</a></p><p>This directory is the <strong>Single Source of Truth</strong> for BrandHub&#39;s business domain model, organizational hierarchy, <strong>6 Canonical System Roles</strong> (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), <strong>141 Atomic Functional Requirements (<code>3.2.1</code>–<code>3.10.14</code>)</strong>, and <strong>141 Use Cases (<code>UC-001</code>–<code>UC-141</code>)</strong>, synchronized 1-to-1 with <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> and <code>brandhub-final_report/report3/report3_official.docx</code>.</p><hr><h2 id="_1-product-vision-two-product-lines-hybrid-operating-modes" tabindex="-1">1. Product Vision, Two Product Lines &amp; Hybrid Operating Modes <a class="header-anchor" href="#_1-product-vision-two-product-lines-hybrid-operating-modes" aria-label="Permalink to &quot;1. Product Vision, Two Product Lines &amp; Hybrid Operating Modes&quot;">​</a></h2><p><strong>BrandHub</strong> is an AI-powered multi-channel media campaign and content operations platform operating on a <strong>Hybrid Multi-Tenant Architecture</strong> across <strong>2 product lines (6 subscription plans)</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Workspace Mode (<code>workspaceMode</code>)</th><th style="text-align:left;">Canonical Plan Line</th><th style="text-align:left;">Target Audience</th><th style="text-align:left;">Core Operational Workflow</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>AGENCY</code> (B2B Media Agency Suite)</strong></td><td style="text-align:left;"><code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code></td><td style="text-align:left;">Marketing/PR agencies managing multiple external brand clients (<code>Client</code>) with specialized creative &amp; account teams.</td><td style="text-align:left;">Structured 3-stage commercial governance: <strong><code>1. Media Package → 2. Media Campaign → 3. Multi-Role Task &amp; Section Execution</code></strong>, dedicated <code>Client Portal</code>, <code>Content Request</code> intake, and strict 3-tier approval (<code>Creator -&gt; Manager -&gt; Client</code>).</td></tr><tr><td style="text-align:left;"><strong><code>PERSONAL</code> (AI Studio for Solo &amp; Small Teams)</strong></td><td style="text-align:left;"><code>STUDIO_FREE</code>, <code>STUDIO_PLUS</code>, <code>STUDIO_PRO</code></td><td style="text-align:left;">Independent creators, freelancers, Marketing/Communications student project teams, and solo brand owners.</td><td style="text-align:left;">One-click <strong>Personal Studio Bootstrap</strong> (backed by a hidden <code>Personal Hub Agency</code>). <strong>Bypasses <code>Media Package</code> negotiation and requires no <code>Client</code></strong>: supports free-form personal campaigns or standalone tasks across all 8 <code>TaskType</code>s, 1-click <strong><code>Self-Approve</code></strong>, teammate <code>Creator</code> invitations, and lossless scale-up to <code>AGENCY</code> mode at any time.</td></tr></tbody></table><hr><h2 id="_2-six-canonical-system-roles-mandatory-naming-standard" tabindex="-1">2. Six Canonical System Roles (Mandatory Naming Standard) <a class="header-anchor" href="#_2-six-canonical-system-roles-mandatory-naming-standard" aria-label="Permalink to &quot;2. Six Canonical System Roles (Mandatory Naming Standard)&quot;">​</a></h2><p>Across all code, API contracts, database seeders, UML diagrams, and SRS/SDD reports, BrandHub strictly enforces <strong>exact 6 short role names</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Canonical Role</th><th style="text-align:center;">Enum Constant</th><th style="text-align:left;">Scope</th><th style="text-align:left;">Core Responsibilities</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>Guest</code></strong></td><td style="text-align:center;"><code>GUEST</code></td><td style="text-align:left;">Public (Unauthenticated)</td><td style="text-align:left;">Browse landing pages, register (<code>3.2.1</code>), sign in (<code>3.2.2</code>, <code>3.2.3</code>), reset password (<code>3.2.4</code>), verify OTP (<code>3.2.6</code>), submit public surveys, and view public <code>ShareLink</code> deliverables (<code>/s/:token</code>).</td></tr><tr><td style="text-align:left;"><strong><code>Owner</code></strong></td><td style="text-align:center;"><code>OWNER</code></td><td style="text-align:left;"><code>Agency</code> (incl. <code>Personal Hub</code>)</td><td style="text-align:left;">Owns an <code>Agency</code> (<code>agencies.owner_id</code>). Governs agency profile, members, workspace templates, <strong>SePay (VietQR)</strong> plan upgrades (<code>3.9.1</code>–<code>3.9.2</code>), <code>agency_credit_wallets</code>, per-workspace AI credit caps (<code>3.9.6 Set Credit</code>), workspaces, and template <code>MediaPackage</code>s.</td></tr><tr><td style="text-align:left;"><strong><code>Manager</code></strong></td><td style="text-align:center;"><code>MANAGER</code></td><td style="text-align:left;"><code>Workspace</code></td><td style="text-align:left;">Leads day-to-day execution of a <code>Workspace</code> (every active Workspace has ≥1 <code>Manager</code>): negotiates/approves packages &amp; campaigns, manages workspace members, defines &amp; assigns tasks/subtasks, performs intermediate review (<code>Creator -&gt; Manager -&gt; Client</code>) or 1-click <code>Self-Approve</code> in <code>PERSONAL</code> mode, connects social channels, and coordinates mail/library assets.</td></tr><tr><td style="text-align:left;"><strong><code>Creator</code></strong></td><td style="text-align:center;"><code>CREATOR</code></td><td style="text-align:left;"><code>Workspace</code></td><td style="text-align:left;">Executes creative production across <strong>8 <code>TaskType</code>s</strong> and role-scoped <code>TaskSection</code>s, writes Unicode-styled copy, applies watermarks &amp; hashtags, uses AI Studio (Caption, Image, Video, Virtual Ambassador), runs safety compliance checks (<code>3.6.33</code>), and schedules/publishes approved posts.</td></tr><tr><td style="text-align:left;"><strong><code>Client</code></strong></td><td style="text-align:center;"><code>CLIENT</code></td><td style="text-align:left;"><code>Workspace</code> (<code>AGENCY</code> mode)</td><td style="text-align:left;">External brand representative backed by a reusable cross-agency <code>ClientProfile</code>: negotiates/approves <code>WorkspaceMediaPackage</code>s &amp; <code>MediaCampaign</code>s, submits <code>Content Request</code>s, uploads Brand Guideline RAG documents, connects official brand social accounts, and executes final <code>Client</code> approval.</td></tr><tr><td style="text-align:left;"><strong><code>Admin</code></strong></td><td style="text-align:center;"><code>ADMIN</code></td><td style="text-align:left;">Platform-wide (<code>SystemRole</code>)</td><td style="text-align:left;">Broadcasts system notifications, monitors platform KPIs &amp; 5-host microservice health (<code>3.10.3</code>), adjudicates the <code>Content Moderation Queue</code> (<code>3.10.4</code>), manages user accounts &amp; violation strikes, configures AI trend crawler schedules (<code>3.7.13</code>), governs AI Credit pricing (<code>3.10.10</code>–<code>3.10.12</code>), tracks SePay revenue, and exports PDF reports.</td></tr></tbody></table><hr><h2 id="_3-master-domain-map-—-141-atomic-frs-141-use-cases" tabindex="-1">3. Master Domain Map — 141 Atomic FRs &amp; 141 Use Cases <a class="header-anchor" href="#_3-master-domain-map-—-141-atomic-frs-141-use-cases" aria-label="Permalink to &quot;3. Master Domain Map — 141 Atomic FRs &amp; 141 Use Cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:center;">SRS Sec.</th><th style="text-align:left;">Functional Domain</th><th style="text-align:center;">FR Range</th><th style="text-align:center;">FRs</th><th style="text-align:center;">UC Range</th><th style="text-align:left;">BA Specification</th><th style="text-align:left;">Use Cases</th><th style="text-align:left;">SRS Feature Folder</th></tr></thead><tbody><tr><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:left;"><strong>Organization Structure &amp; Hybrid Tenancy</strong></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:left;"><a href="./01-organization-structure.html">01-organization-structure.md</a></td><td style="text-align:left;">—</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;"><code>3.2</code></td><td style="text-align:left;"><strong>Authentication &amp; Authorization</strong></td><td style="text-align:center;"><code>3.2.1</code>–<code>3.2.9</code></td><td style="text-align:center;"><strong>9</strong></td><td style="text-align:center;"><code>UC-001</code>–<code>UC-009</code></td><td style="text-align:left;"><a href="./02-authentication-profile.html">02-authentication-profile.md</a></td><td style="text-align:left;"><a href="./use-cases/01-authentication-profile.html">01-authentication-profile.md</a></td><td style="text-align:left;"><a href="./../feature/srs/01-authentication/README.html">01-authentication</a></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;"><code>3.3</code></td><td style="text-align:left;"><strong>User &amp; Client Profile</strong></td><td style="text-align:center;"><code>3.3.1</code>–<code>3.3.4</code></td><td style="text-align:center;"><strong>4</strong></td><td style="text-align:center;"><code>UC-010</code>–<code>UC-013</code></td><td style="text-align:left;"><a href="./02-authentication-profile.html">02-authentication-profile.md</a></td><td style="text-align:left;"><a href="./use-cases/01-authentication-profile.html">01-authentication-profile.md</a></td><td style="text-align:left;"><a href="./../feature/srs/02-profile/README.html">02-profile</a></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;"><code>3.4</code></td><td style="text-align:left;"><strong>Agency &amp; Workspace</strong></td><td style="text-align:center;"><code>3.4.1</code>–<code>3.4.26</code></td><td style="text-align:center;"><strong>26</strong></td><td style="text-align:center;"><code>UC-014</code>–<code>UC-039</code></td><td style="text-align:left;"><a href="./03-agency-workspace.html">03-agency-workspace.md</a></td><td style="text-align:left;"><a href="./use-cases/02-agency-workspace.html">02-agency-workspace.md</a></td><td style="text-align:left;"><a href="./../feature/srs/03-agency-workspace/README.html">03-agency-workspace</a></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;"><code>3.5</code></td><td style="text-align:left;"><strong>Media Package &amp; Media Campaign</strong></td><td style="text-align:center;"><code>3.5.1</code>–<code>3.5.13</code></td><td style="text-align:center;"><strong>13</strong></td><td style="text-align:center;"><code>UC-040</code>–<code>UC-052</code></td><td style="text-align:left;"><a href="./04-media-package-campaign.html">04-media-package-campaign.md</a></td><td style="text-align:left;"><a href="./use-cases/03-media-package-campaign.html">03-media-package-campaign.md</a></td><td style="text-align:left;"><a href="./../feature/srs/04-media-package-campaign/README.html">04-media-package-campaign</a></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;"><code>3.6</code></td><td style="text-align:left;"><strong>Content &amp; Workflow</strong></td><td style="text-align:center;"><code>3.6.1</code>–<code>3.6.35</code></td><td style="text-align:center;"><strong>35</strong></td><td style="text-align:center;"><code>UC-053</code>–<code>UC-087</code></td><td style="text-align:left;"><a href="./05-content-task-workflow.html">05-content-task-workflow.md</a></td><td style="text-align:left;"><a href="./use-cases/04-content-task-workflow.html">04-content-task-workflow.md</a></td><td style="text-align:left;"><a href="./../feature/srs/05-content-task-workflow/README.html">05-content-task-workflow</a></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;"><code>3.7</code></td><td style="text-align:left;"><strong>AI Features</strong></td><td style="text-align:center;"><code>3.7.1</code>–<code>3.7.19</code></td><td style="text-align:center;"><strong>19</strong></td><td style="text-align:center;"><code>UC-088</code>–<code>UC-106</code></td><td style="text-align:left;"><a href="./06-ai-features.html">06-ai-features.md</a></td><td style="text-align:left;"><a href="./use-cases/05-ai-features.html">05-ai-features.md</a></td><td style="text-align:left;"><a href="./../feature/srs/06-ai-features/README.html">06-ai-features</a></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;"><code>3.8</code></td><td style="text-align:left;"><strong>Publishing &amp; Social</strong></td><td style="text-align:center;"><code>3.8.1</code>–<code>3.8.15</code></td><td style="text-align:center;"><strong>15</strong></td><td style="text-align:center;"><code>UC-107</code>–<code>UC-121</code></td><td style="text-align:left;"><a href="./07-publishing-social.html">07-publishing-social.md</a></td><td style="text-align:left;"><a href="./use-cases/06-publishing-social.html">06-publishing-social.md</a></td><td style="text-align:left;"><a href="./../feature/srs/07-publishing-social/README.html">07-publishing-social</a></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;"><code>3.9</code></td><td style="text-align:left;"><strong>Subscription &amp; Billing</strong></td><td style="text-align:center;"><code>3.9.1</code>–<code>3.9.6</code></td><td style="text-align:center;"><strong>6</strong></td><td style="text-align:center;"><code>UC-122</code>–<code>UC-127</code></td><td style="text-align:left;"><a href="./08-subscription-billing.html">08-subscription-billing.md</a></td><td style="text-align:left;"><a href="./use-cases/07-subscription.html">07-subscription.md</a></td><td style="text-align:left;"><a href="./../feature/srs/08-subscription-billing/README.html">08-subscription-billing</a></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;"><code>3.10</code></td><td style="text-align:left;"><strong>Admin Functions</strong></td><td style="text-align:center;"><code>3.10.1</code>–<code>3.10.14</code></td><td style="text-align:center;"><strong>14</strong></td><td style="text-align:center;"><code>UC-128</code>–<code>UC-141</code></td><td style="text-align:left;"><a href="./09-admin-functions.html">09-admin-functions.md</a></td><td style="text-align:left;"><a href="./use-cases/08-admin-functions.html">08-admin-functions.md</a></td><td style="text-align:left;"><a href="./../feature/srs/09-admin-functions/README.html">09-admin-functions</a></td></tr><tr><td style="text-align:center;"><strong>Total</strong></td><td style="text-align:center;"></td><td style="text-align:left;"><strong>9 Canonical Domains</strong></td><td style="text-align:center;"><strong><code>3.2.1</code>–<code>3.10.14</code></strong></td><td style="text-align:center;"><strong>141</strong></td><td style="text-align:center;"><strong><code>UC-001</code>–<code>UC-141</code></strong></td><td style="text-align:left;"></td><td style="text-align:left;"><a href="./use-cases/README.html">Use Case Hub</a></td><td style="text-align:left;"><a href="./../feature/README.html">Feature Hub</a></td></tr></tbody></table><h3 id="cross-cutting-ba-reference-specifications" tabindex="-1">Cross-Cutting BA Reference Specifications <a class="header-anchor" href="#cross-cutting-ba-reference-specifications" aria-label="Permalink to &quot;Cross-Cutting BA Reference Specifications&quot;">​</a></h3><ul><li><a href="./10-roles-permissions-matrix.html">10-roles-permissions-matrix.md</a> — Complete <code>6-Role × 141-FR</code> authorization matrix + <code>SectionPolicy</code> subtask matrix.</li><li><a href="./11-data-entities-glossary.html">11-data-entities-glossary.md</a> — Domain entity dictionary across PostgreSQL (<code>97</code> tables), MongoDB (<code>52</code> collections), ChromaDB, Neo4j, and Redis.</li><li><a href="./12-state-machines.html">12-state-machines.md</a> — Formal lifecycle state machines for Workspaces, Packages, Campaigns, Content Requests, Tasks, <code>TaskSection</code>s, Social Posts, Mail Batches, SePay Invoices, Credit Reservations, and Moderation.</li><li><a href="./13-task-status-and-approval-governance.html">13-task-status-and-approval-governance.md</a> — End-to-end multi-role authorization (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code> × <code>Coordinator</code>, <code>Task Supervisor</code>, <code>Section Owner</code>), automatic <code>Section → Subtask → Task</code> status settlement, and anti-bypass guards.</li><li>Financial &amp; unit-economics workbook in this folder: <code>docs/ba/brandhub-pricing-model.xlsx</code> (models <code>STUDIO_FREE/PLUS/PRO</code> + <code>BASIC/PLUS/ENTERPRISE</code> pricing &amp; AI Credit margins).</li></ul><hr><h2 id="_4-eight-canonical-task-types-tasktype-multi-section-editor-tasksection" tabindex="-1">4. Eight Canonical Task Types (<code>TaskType</code>) &amp; Multi-Section Editor (<code>TaskSection</code>) <a class="header-anchor" href="#_4-eight-canonical-task-types-tasktype-multi-section-editor-tasksection" aria-label="Permalink to &quot;4. Eight Canonical Task Types (`TaskType`) &amp; Multi-Section Editor (`TaskSection`)&quot;">​</a></h2><p>Every work item in BrandHub belongs to <strong>1 of 8 canonical <code>TaskType</code>s</strong>, decomposed into role-specific <code>TaskSection</code> blocks (Internal <code>I</code> vs. Client-facing Output <code>O</code>):</p><ol><li><strong><code>POST</code></strong> — Social media post (<code>POST.BRIEF</code>, <code>POST.CAPTION</code>, <code>POST.MEDIA</code>, <code>POST.CHANNELS</code>).</li><li><strong><code>SHORT_VIDEO</code></strong> — Vertical short-form video for TikTok / Reels (<code>VIDEO.SCRIPT</code>, <code>VIDEO.SHOOT</code>, <code>VIDEO.EDIT</code>, <code>VIDEO.CAPTION</code>, <code>VIDEO.CHANNELS</code>).</li><li><strong><code>SURVEY</code></strong> — Public interactive survey (<code>SURVEY.FORM</code>, <code>SURVEY.DISTRIBUTION</code>, <code>SURVEY.REPORT</code>).</li><li><strong><code>EVENT_PLAN</code></strong> — Offline/hybrid event plan (<code>EVENT.AGENDA</code>, <code>EVENT.LOGISTICS</code>, <code>EVENT.PROMOTION</code>, <code>EVENT.RUNSHEET</code>, <code>EVENT.REPORT</code>).</li><li><strong><code>PRESS_RECOMMENDATION</code></strong> — PR media list &amp; press release (<code>PRESS.MEDIA_LIST</code>, <code>PRESS.RELEASE</code>, <code>PRESS.CONTACT_LOG</code>, <code>PRESS.COVERAGE</code>).</li><li><strong><code>KOL_BOOKING</code></strong> — Influencer / KOL collaboration (<code>KOL.SHORTLIST</code>, <code>KOL.DEAL</code>, <code>KOL.BRIEF</code>, <code>KOL.DRAFT</code>, <code>KOL.REPORT</code>).</li><li><strong><code>WORKSHOP</code></strong> — Workshop / seminar program (<code>WORKSHOP.PROGRAM</code>, <code>WORKSHOP.SPEAKERS</code>, <code>WORKSHOP.LOGISTICS</code>, <code>WORKSHOP.REGISTRATION</code>, <code>WORKSHOP.REPORT</code>).</li><li><strong><code>EMAIL_NEWSLETTER</code></strong> — Real SMTP newsletter batch (<code>EMAIL.CONTENT</code>, <code>EMAIL.DESIGN</code>, <code>EMAIL.AUDIENCE</code>, <code>EMAIL.REPORT</code>).</li></ol><hr><h2 id="_5-non-negotiable-scope-guardrails-de-scoped-features" tabindex="-1">5. Non-Negotiable Scope Guardrails &amp; De-Scoped Features <a class="header-anchor" href="#_5-non-negotiable-scope-guardrails-de-scoped-features" aria-label="Permalink to &quot;5. Non-Negotiable Scope Guardrails &amp; De-Scoped Features&quot;">​</a></h2><ol><li><strong>No Livestream Features</strong>: No <code>LIVESTREAM</code> task type, livestream scripts, or AI livestream assistants.</li><li><strong>No Plan Downgrade Flow</strong>: Upgrade-only subscription lifecycle (<code>3.9.1 Upgrade Plan</code>).</li><li><strong>No Plagiarism / Copyright Check FR</strong>: Retain only community safety compliance (<code>3.6.33 Check Compliance Content</code>) and Admin moderation (<code>3.10.4 Content Moderation Queue</code>).</li><li><strong>Strictly 4 Social Publishing Platforms</strong>: <strong>Facebook, Instagram, TikTok, and Threads</strong> (no Zalo OA, no YouTube).</li><li><strong>Strictly SePay (VietQR) Payment Gateway</strong>: No PayOS, VNPay, or Stripe.</li><li><strong>Zero <code>&quot;Manage&quot;</code> Rule</strong>: Every FR and Use Case title uses an atomic verb (<code>View</code>, <code>Create</code>, <code>Update</code>, <code>Delete/Remove</code>, <code>Approve</code>, <code>Publish</code>, etc.)—never <code>&quot;Manage ...&quot;</code> or <code>&quot;... Management&quot;</code>.</li></ol>',23)])])}const y=t(n,[["render",c]]);export{p as __pageData,y as default};
